// 1. Получаем все входящие данные
const results = $input.all();

// 2. Получаем данные из узла 'Обогатитель данных'
let filteredSource = [];
try {
    // В n8n 1.0+ используем $('Имя узла') без квадратных скобок
    const sourcePlan = $('Обогатитель данных').all();
    const currentTypes = ['TEXT', 'RESEARCH', 'QUOTE']; 

    // Фильтруем заранее
    filteredSource = sourcePlan.filter(item => 
        item.json && item.json.type && currentTypes.includes(item.json.type)
    );
} catch (e) {
    // Если узел не найден, filteredSource останется пустым массивом
    console.error("Ошибка доступа к узлу 'Обогатитель данных':", e.message);
}

// 3. Обработка каждого из 7 входящих итемов
return results.map((item, index) => {
    // Безопасно ищем соответствие в filteredSource
    const original = filteredSource[index] ? filteredSource[index].json : {};

    // Гарантируем наличие строки
    let content = String(item.json.output || item.json.final_html || "").trim();

    /**
     * САНИТАЙЗЕР
     */

    // Удаляем блоки кода Markdown (```html ... ```)
    // Используем простое и надежное регулярное выражение
    content = content.replace(/```(?:html|HTML)?/gi, '').replace(/```/g, '').trim();

    // Удаляем слово "html" в самом начале
    if (content.toLowerCase().startsWith('html')) {
        content = content.replace(/^html\s+/i, '').trim();
    }

    // Удаляем Markdown-заголовки (решетки) в начале
    content = content.replace(/^(?:#+\s?.*\n?)+/g, '').trim();

    // Возвращаем объект в формате n8n
    return {
        json: {
            id: original.id || null,
            type: original.type || null,
            h2_title: original.h2_title || null,
            result: content
        }
    };
});

/**
 * ОПИСАНИЕ: Улучшенная версия с защитой от "зависания"
 */

// 1. Получаем все данные из узла Switch
// Важно: Убедитесь, что узел называется именно "Switch" (без кавычек в названии)
let allSourceItems = [];
try {
    allSourceItems = $('Switch').all();
} catch (e) {
    throw new Error("Не удалось получить данные из узла 'Switch'. Проверьте, что он выполнен.");
}

// 2. Фильтруем блоки типа IMG
const imgSourceBlocks = allSourceItems.filter(item => item.json && item.json.type === 'IMG');

// 3. Обрабатываем входящие результаты
return $input.all().map((item, index) => {
    // Берем исходные данные по индексу
    const originalItem = imgSourceBlocks[index];

    // Защита: если вдруг оригинальный блок не найден, берем пустой объект
    const original = originalItem ? originalItem.json : {};

    // В качестве подписи используем h2_title или стандартную фразу
    const captionText = original.h2_title || "Иллюстрация к материалу";

    // Данные из текущего инпута (результат генерации)
    const mediaUrl = item.json.mediaUrl || '';
    const altText = item.json.altText || original.h2_title || '';
    const mediaId = item.json.mediaId || '0';

    // Формируем HTML
    const htmlImage = `
<figure class="wp-block-image aligncenter size-large" style="margin: 24px auto; text-align: center;">
  <img 
    src="${mediaUrl}" 
    alt="${altText}" 
    class="wp-image-${mediaId}" 
    style="width: 100%; max-width: 800px; height: auto; border-radius: 12px; display: block; margin: 0 auto; box-shadow: 0 4px 15px rgba(0,0,0,0.1);"
    loading="lazy"
  />
  <figcaption style="font-size: 14px; color: #777; margin-top: 10px; font-style: italic; line-height: 1.4;">
    ${captionText}
  </figcaption>
</figure>`.trim();

    return {
        json: {
            id: original.id || null,
            type: original.type || 'IMG',
            h2_title: original.h2_title || '',
            result: htmlImage 
        }
    };
});

/**
 * ОПИСАНИЕ УЗЛА: "Финальная сортировка" V.2.0
 */

// 1. Получаем массив частей (безопасно)
const input = $json.parts || [];

// 2. Убираем блоки, у которых нет ID (лишние галлюцинации ИИ или ошибки сопоставления)
const validParts = input.filter(item => item.id !== null && item.id !== undefined);

// 3. Сортируем только валидные блоки по ID
validParts.sort((a, b) => {
  return (Number(a.id) || 0) - (Number(b.id) || 0);
});

// 4. Добавляем мета-данные верстки
const bricks = validParts.map(block => {
  // Определяем тег заголовка
  let headerTag = 'h2';

  // H3 для технических блоков
  if (['TABLE', 'STEPS', 'SOFT_OFFER'].includes(block.type)) {
    headerTag = 'h3';
  }

  // У картинок и офферов заголовка может не быть в верстке
  if (block.type === 'IMG' || block.type === 'HARD_OFFER') {
    headerTag = null; 
  }

  return {
    id: block.id,
    type: block.type,
    title: block.h2_title || "",
    header_tag: headerTag,
    content: block.result
  };
});

// 5. Возвращаем результат
return [
  {
    json: {
      blocks: bricks,
      total_blocks: bricks.length
    }
  }
];

