// Оставляем первый блок для истории, но не для поиска
const plan = $json.final_plan.blocks || [];
const bodyPlan = plan.slice(1);

// Формируем массив задач для поиска
const searchTasks = bodyPlan
  .filter(b => b.perplexity_intent && b.perplexity_intent !== null)
  .map(b => {
    return {
      block_id: b.id,
      type: b.type || null,
      h2: b.h2_title || null,
      query: b.perplexity_intent,
      context: b.context || null,

      external_url: b.external_linking?.url || null,
      external_portal: b.external_linking?.portal || null,
      external_description: b.external_linking?.description || null,

      internal_url: b.internal_linking?.url || null,
      internal_anchor: b.internal_linking?.anchor || null,
      internal_topic: b.internal_linking?.topic || null,

      offer_id: b.offer_id || null,
      offer_url: b.offer_url || null,
    };
  });

// Возвращаем как список элементов для n8n (Split Out)
return searchTasks;

/**
 * Скрипт обработки ТЕХ-блоков (V.3.3 Stable)
 */

// 1. Получаем данные напрямую из узлов
const mainItems = $('Технический писатель').all();
let sourcePlan = [];
try {
    sourcePlan = $('Обогатитель данных').all();
} catch (e) {
    console.log("Узел 'Обогатитель данных' не найден");
}

// 2. УСТАНОВКА ФИЛЬТРА:
const currentTypes = ['TABLE', 'STEPS', 'VIDEO', 'HARD_OFFER', 'SOFT_OFFER'];
const filteredSource = sourcePlan.filter(item => 
    item.json && item.json.type && currentTypes.includes(item.json.type)
);

// --- ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ (Сохранены полностью) ---

function stripTags(value) {
    return String(value || '')
        .replace(/<[^>]+>/g, ' ')
        .replace(/&nbsp;/gi, ' ')
        .replace(/\s+/g, ' ')
        .trim();
}

function escapeHtml(value) {
    return String(value || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function escapeAttribute(value) {
    return escapeHtml(value);
}

function normalizeHardOffer(html) {
    if (!html || !html.includes('hard-cta-box')) return html;
    let normalized = html;

    normalized = normalized.replace(/<div([^>]*class=["'][^"']*hard-cta-box[^"']*["'][^>]*)style=(["'])(.*?)\2([^>]*)>/i, (_match, before, quote, style, after) => {
        const cleanedStyle = String(style).replace(/background\s*:[^;]+;?/gi, '').replace(/color\s*:[^;]+;?/gi, '').replace(/!important/gi, '').trim();
        const baseStyle = 'background: #111827; color: #fff;';
        return `<div${before}style=${quote}${cleanedStyle ? baseStyle + ' ' + cleanedStyle : baseStyle}${quote}${after}>`;
    });

    normalized = normalized.replace(/<h3([^>]*)style=(["'])(.*?)\2([^>]*)>/i, (_match, before, quote, style, after) => {
        const cleanedStyle = String(style).replace(/color\s*:[^;]+;?/gi, '').replace(/!important/gi, '').trim();
        return `<h3${before}style=${quote}${cleanedStyle ? 'color: #fff; ' + cleanedStyle : 'color: #fff;'}${quote}${after}>`;
    });

    normalized = normalized.replace(/<p([^>]*)style=(["'])(.*?)\2([^>]*)>([\s\S]*?)<\/p>/gi, (match, before, quote, style, after, inner) => {
        if (String(inner).includes('<a ')) return match;
        const cleanedStyle = String(style).replace(/color\s*:[^;]+;?/gi, '').replace(/!important/gi, '').trim();
        return `<p${before}style=${quote}${cleanedStyle ? 'color: #fff; ' + cleanedStyle : 'color: #fff;'}${quote}${after}>${inner}</p>`;
    });

    return normalized;
}

function normalizeSoftOffer(html, original) {
    const rawHtml = String(html || '').trim();
    const firstAnchorMatch = rawHtml.match(/<a[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/i);
    const paragraphMatches = [...rawHtml.matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)];

    const introFromParagraph = paragraphMatches.find(match => !String(match[1]).includes('<a '));
    const introText = stripTags(introFromParagraph ? introFromParagraph[1] : rawHtml);

    const offerUrl = firstAnchorMatch?.[1] || original?.full_offer?.ссылка || original?.offer_url || '';
    const anchorRawText = stripTags(firstAnchorMatch?.[2] || '');
    const offerName = anchorRawText || original?.full_offer?.название || original?.offer_title || original?.h2_title || 'Перейти';
    const linkLabel = /перейти/i.test(offerName) ? offerName : `${offerName} — Перейти →`;

    return `<div class="ad-box" style="padding: 20px; border-left: 4px solid #7a00ff; background: #f9f9f9; margin: 25px 0; text-align: left;">\n  <p><strong>${escapeHtml(introText || 'Узнайте подробности по ссылке ниже.')}</strong></p>\n  <p><a href="${escapeAttribute(offerUrl)}" target="_blank" rel="nofollow noopener" style="color: #7a00ff; text-decoration: underline;">${escapeHtml(linkLabel)}</a></p>\n</div>`;
}

// --- ОСНОВНОЙ ЦИКЛ (7 айтемов на входе -> 7 на выходе) ---

return mainItems.map((item, index) => {
    // Безопасно сопоставляем с Обогатителем
    const original = filteredSource[index] ? filteredSource[index].json : {};

    // Берем контент из Гонзо-Журналист
    let content = String(item.json.output || item.json.final_html || "").trim();

    /**
     * САНИТАЙЗЕР (Regex вместо while):
     * Удаляет все строки, начинающиеся с # в начале текста.
     */
    content = content.replace(/^(?:#+\s?.*\n?)+/g, '').trim();

    // Обработка по типу
    if (original.type === 'HARD_OFFER') {
        content = normalizeHardOffer(content);
    }

    if (original.type === 'SOFT_OFFER') {
        content = normalizeSoftOffer(content, original);
    }

    // Возвращаем объект
    return {
        json: {
            id: original.id || null,
            type: original.type || null,
            h2_title: original.h2_title || null,
            result: content
        }
    };
});

/**
 * УЗЕЛ: Обогатитель данных
 * ЧТО ДЕЛАЕТ:
 * 1. Соединяет план Архитектора с результатами поиска Perplexity.
 * 2. Разворачивает offer_id в полные данные.
 * 3. Обновляет research_data и linking-поля блока.
 */

const researchItems = $items("Message a model");
const researchMap = {};

// Собираем карту исследований по block_id
researchItems.forEach(item => {
	try {
		let raw = item.json?.choices?.[0]?.message?.content || '';
		if (!raw) return;

		raw = raw.replace(/```json\s*|```/g, '').trim();

		const parsed = JSON.parse(raw);

		if (parsed && parsed.block_id !== undefined && parsed.block_id !== null) {
			researchMap[String(parsed.block_id)] = {
				research_summary: parsed.research_summary || "Данные из досье.",
				external_linking: parsed.external_linking || null,
				internal_linking: parsed.internal_linking || null,
			};
			return;
		}

		// Legacy fallback: {"ID": "text"}
		if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
			const keys = Object.keys(parsed);
			if (keys.length === 1) {
				const id = keys[0];
				researchMap[String(id)] = {
					research_summary: parsed[id] || "Данные из досье.",
					external_linking: null,
					internal_linking: null,
				};
			}
		}
	} catch (e) {
		console.log("Research output is not valid JSON:", e.message);
	}
});

// Источник плана и контекста
const triggerItem = $('When Executed by Another Workflow').first().json;
const planBlocks = triggerItem.final_plan?.blocks || [];
const offersDb = triggerItem.контекст?.база_офферов || [];

// Собираем enriched items
return planBlocks
	.filter(b => b.id !== 1)
	.map(block => {
		const research = researchMap[String(block.id)] || null;

		const blockFacts = research?.research_summary || "Данные из досье.";

		let fullOfferData = null;
		if (block.offer_id !== null && block.offer_id !== undefined && block.offer_id !== '') {
			fullOfferData = offersDb.find(o => String(o.id) === String(block.offer_id)) || null;
		}

		const external_linking =
			research?.external_linking !== undefined && research?.external_linking !== null
				? research.external_linking
				: (block.external_linking || null);

		const internal_linking =
			research?.internal_linking !== undefined && research?.internal_linking !== null
				? research.internal_linking
				: (block.internal_linking || null);

		const offer_url =
			fullOfferData?.ссылка ||
			block.offer_url ||
			null;

		return {
			json: {
				...block,
				external_linking,
				internal_linking,
				offer_url,
				research_data: blockFacts,
				full_offer: fullOfferData,
				video_data: block.video_data || null,
				languageCode: triggerItem.languageCode,
			}
		};
	});

// 1. Получаем все входящие элементы (используем $input.all() вместо items)
const items = $input.all();

// 2. Пытаемся безопасно достать "Главный ключ" из контекста один раз
let mainKey = "статьи";
try {
  // Используем .first().json и опциональную цепочку ?.
  const context = $('When Executed by Another Workflow').first().json;
  mainKey = context?.контекст?.задача?.['Главный ключ'] || "статьи";
} catch (e) {
  // Если узел недоступен, останется дефолтное "статьи"
  console.log("Контекст недоступен:", e.message);
}

// 3. Обрабатываем каждый элемент
return items.map(item => {
  const raw = String(item.json?.output || '').trim();

  // Пытаемся найти JSON регуляркой
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  let parsed = null;

  if (jsonMatch) {
    try {
      // Очищаем от невидимых символов управления и парсим
      const cleanCandidate = jsonMatch[0].replace(/[\u0000-\u001F\u007F-\u009F]/g, "");
      parsed = JSON.parse(cleanCandidate);
    } catch (e) {
      parsed = null;
    }
  }

  // ✅ ВАРИАНТ А: Если парсинг прошел успешно
  if (parsed && typeof parsed === 'object') {
    return {
      json: {
        technical_prompt: parsed.technical_prompt || "Error: prompt missing",
        alt_text: parsed.alt_text || `Изображение для ${mainKey}` 
      }
    };
  }

  // ✅ ВАРИАНТ Б: Если это просто текст (не JSON)
  // Берем первые 500 символов как промпт
  return {
    json: {
      technical_prompt: raw.slice(0, 500) || "Error: empty input", 
      alt_text: "Изображение для " + mainKey
    }
  };
});

message.content:
=Проведи исследование для одного блока статьи.

ДАННЫЕ БЛОКА:
- Block ID: {{ $json.block_id }}
- Тип блока: {{ $json.type }}
- Заголовок H2: {{ $json.h2 }}
- Поисковый запрос: {{ $json.query }}
- Контекст блока: {{ $json.context }}

УЖЕ ИЗВЕСТНЫЕ ССЫЛКИ:
- Внешний URL: {{ $json.external_url || 'null' }}
- Внешний портал: {{ $json.external_portal || 'null' }}
- Описание внешнего источника: {{ $json.external_description || 'null' }}
- Внутренний URL: {{ $json.internal_url || 'null' }}
- Внутренний анкор: {{ $json.internal_anchor || 'null' }}
- Внутренняя тема: {{ $json.internal_topic || 'null' }}

ЗАДАЧА:
1. Выполни поиск строго под этот блок.
2. Используй `query` как основной поисковый запрос.
3. Учитывай `h2` и `context`, чтобы понять, какой именно факт нужен.
4. Если внешний URL уже передан, сначала проверь, подходит ли он именно для этого блока.
5. Если текущий внешний URL реально релевантен и подтверждает тезис блока, сохрани его.
6. Если текущий внешний URL слабый, нерелевантный, битый или не подтверждает тезис, найди более точный внешний источник.
7. Если надежного внешнего источника нет, верни `external_linking: null`.
8. Если внутренний URL уже есть, сохрани его без изменений.
9. Если внутреннего URL нет, не выдумывай его, верни `internal_linking: null`.
10. Сделай краткую, но плотную research-выжимку именно для этого блока.

Верни строго JSON-объект в таком формате:

{
  "block_id": {{ $json.block_id }},
  "research_summary": "Краткая выжимка найденных фактов для этого блока.",
  "external_linking": {
    "url": "https://...",
    "portal": "Название портала",
    "description": "Какой факт подтверждает источник"
  },
  "internal_linking": {
    "url": "https://...",
    "anchor": "Анкор",
    "topic": "Тема"
  }
}

Важно:
- не меняй `block_id`
- не возвращай markdown
- не добавляй пояснений
- верни только JSON
